function validate([nums, target]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -10000 || v > 10000)) return 'Each value of nums is a whole number from -10^4 to 10^4.';
  if (!Number.isInteger(target) || target < 0 || target > 1000000) return 'target is a whole number from 0 to 10^6.';
  return null;
}

