function maxNonOverlapping(nums, target) {
  // best[i] is the answer for the first i elements: either skip element i - 1,
  // or end a subarray nums[j..i-1] with sum target there and add 1 to best[j].
  const n = nums.length;
  const best = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    best[i] = best[i - 1];
    let sum = 0;
    for (let j = i - 1; j >= 0; j--) {
      sum += nums[j];
      if (sum === target) best[i] = Math.max(best[i], best[j] + 1);
    }
  }
  return best[n];
}

