function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 1500 + pick(501) : 1 + pick(10);
  const span = size === 'large' ? [5, 50, 10000][pick(3)] : 1 + pick(4);
  const nums = Array.from({ length: n }, () => pick(2 * span + 1) - span);
  const roll = rand();
  // Usually a small target so matches are common; sometimes 0, or the sum of a real subarray.
  let target;
  if (roll < 0.2) target = 0;
  else if (roll < 0.6) target = pick(2 * span + 1);
  else {
    const from = pick(n);
    const to = from + pick(Math.min(n - from, 6));
    target = Math.max(0, nums.slice(from, to + 1).reduce((a, b) => a + b, 0));
  }
  return [nums, target];
}
